"""Painted Arcade arena floors (arena-art pass, 2026-11-13). Original art generated by this script (no legacy pixels used).
Run: ~/claudetmp/v/bin/python tools/assets/stage-gen/arena-floor.py public/assets/img/arenafloor.png   (numpy + Pillow; fixed seeds,
deterministic quantiser, so the output is byte-identical)
Atlas 1920 x 2144: one 1920 x 536 floor per stage, rows in stage order (fire, water, earth, air). src/game/fx/terrain-floor.ts draws
the stage's floor from the wall (world y 184, terrain-stage-layout WALL_Y) to the bottom of the arena; the 32 px tiles of
tilefloor.png (tools/assets/tile-gen/tilefloor.py) only scatter sparse, feathered details over it.
Look (owner, 2026-11-13: the old tile floor read as a flat checker with specks): one continuous painted surface per stage with
depth. Every field is built in "ground space" and squashed toward the wall (features shrink with distance), the wall casts a soft
contact shadow and haze, a broad pool of light sits where the fight is, and each stage has its own large-scale detail: fire is
basalt slabs with a few ember-lit seams, water is wet slate with standing pools that catch a cold light, earth is ruined
flagstones half-sunk in moss and roots, air is pale veined sky-stone swept by thin cloud. Grim and textured, desaturated but
luminous: mid values (luma ~45-120), glows thin and soft, no outlines and no tile grid.
"""
import os
import sys
import numpy as np
from PIL import Image

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "rig-gen"))
import palette  # noqa: E402

W, FH = 1920, 536
# Ground space: rows near the wall are squashed (scale 0.5 at the wall, 1 at the front), so features recede with distance.
GH = int(FH * 2 * np.log(2)) + 2
YY, XX = np.mgrid[0:GH, 0:W].astype(np.float32)
SY, SX = np.mgrid[0:FH, 0:W].astype(np.float32)
V = SY / FH  # 0 at the wall, 1 at the front edge


def noise(seed, cell, aniso=1.0, h=GH):
    r = np.random.default_rng(seed)
    gw, gh = int(W / (cell * aniso)) + 3, int(h / cell) + 3
    g = Image.fromarray((r.random((gh, gw)) * 255).astype(np.uint8)).resize((int(gw * cell * aniso), int(gh * cell)), Image.BICUBIC)
    return np.asarray(g, np.float32)[:h, :W] / 255.0


def fbm(seed, cell, octs=4, aniso=1.0, h=GH):
    t, amp, tot = np.zeros((h, W), np.float32), 1.0, 0.0
    for o in range(octs):
        t += amp * noise(seed + o * 101, max(2.0, cell / (2 ** o)), aniso, h)
        tot += amp
        amp *= 0.5
    return np.clip((t / tot - 0.5) * 2.0 + 0.5, 0, 1)


def blur(a, r):
    k = int(r * 3) + 1
    w = np.exp(-0.5 * (np.arange(-k, k + 1) / r) ** 2).astype(np.float32)
    w /= w.sum()
    out = np.asarray(a, np.float32)
    for ax in (0, 1):
        p = np.pad(out, [(k, k) if i == ax else (0, 0) for i in range(2)], mode="edge")
        acc = np.zeros_like(out)
        n = out.shape[ax]
        for i, wi in enumerate(w):
            acc += wi * (p[i:i + n, :] if ax == 0 else p[:, i:i + n])
        out = acc
    return out


def smooth(x, a, b):
    t = np.clip((x - a) / (b - a), 0, 1)
    return t * t * (3 - 2 * t)


def relief(h, strength, lx=-0.5, ly=-0.85):
    gy, gx = np.gradient(h * strength)
    return np.clip(-(gx * lx + gy * ly) / np.sqrt(1 + gx * gx + gy * gy), -1, 1)


def tint(lum, stops):
    return palette.ramp(stops, np.clip(lum, 0, 1)).astype(np.float32)


def voronoi(seed, cw, ch, warp):
    """Irregular slabs in ground space: (gap to the next cell in px, per-slab random value 0..1)."""
    r = np.random.default_rng(seed)
    nx, ny = W // cw + 4, GH // ch + 4
    jx, jy, val = r.random((ny, nx)), r.random((ny, nx)), r.random((ny, nx))
    xx = XX + (fbm(seed + 1, 90, 3) - 0.5) * warp
    yy = YY + (fbm(seed + 2, 90, 3) - 0.5) * warp
    cx, cy = np.floor(xx / cw).astype(int), np.floor(yy / ch).astype(int)
    d1 = np.full(xx.shape, 1e9, np.float32)
    d2 = np.full(xx.shape, 1e9, np.float32)
    v1 = np.zeros(xx.shape, np.float32)
    for oy in (-1, 0, 1):
        for ox in (-1, 0, 1):
            gx, gy = np.clip(cx + ox + 1, 0, nx - 1), np.clip(cy + oy + 1, 0, ny - 1)
            px = (cx + ox + 0.15 + jx[gy, gx] * 0.7) * cw
            py = (cy + oy + 0.15 + jy[gy, gx] * 0.7) * ch
            d = np.sqrt((xx - px) ** 2 + ((yy - py) * cw / ch) ** 2)
            closer = d < d1
            d2 = np.where(closer, d1, np.minimum(d2, d))
            v1 = np.where(closer, val[gy, gx], v1)
            d1 = np.where(closer, d, d1)
    return d2 - d1, v1


def persp(a):
    """Ground space (GH rows) to screen (FH rows): row y samples ground row g(y) = integral of 1 / (0.5 + 0.5 v)."""
    g = FH * 2 * np.log1p(np.arange(FH, dtype=np.float32) / FH)
    i0 = np.clip(np.floor(g).astype(int), 0, GH - 2)
    f = (g - i0)[:, None] if a.ndim == 2 else (g - i0)[:, None, None]
    return a[i0] * (1 - f) + a[i0 + 1] * f


def stage_light(pool, wall, haze_col, img):
    """Shared grading in screen space: a broad pool of light in the fight zone, the wall's contact shadow and distance haze,
    darker far left and right (the camera rarely rests there) and a slightly darker front edge."""
    d = np.sqrt(((SX / W - 0.5) * 1.6) ** 2 + ((V - 0.5) * 1.15) ** 2)
    lit = 0.62 + 0.5 * (1 - smooth(d, 0.0, 0.85))
    lit = lit * (1 - 0.28 * smooth(np.abs(SX / W - 0.5), 0.3, 0.5))
    lit = lit * (1 - 0.18 * smooth(V, 0.82, 1.0))
    img = img * lit[..., None]
    img = img + (1 - smooth(d, 0.0, 0.7))[..., None] * np.asarray(pool, np.float32) * 0.22  # coloured bounce in the pool
    haze = (1 - smooth(V, 0.0, 0.3)) * 0.38
    img = img * (1 - haze[..., None]) + np.asarray(haze_col, np.float32) * haze[..., None]
    shadow = np.exp(-SY / 16.0) * 0.55 + np.exp(-SY / 60.0) * 0.18  # contact shadow under the wall
    return img * (1 - shadow * wall)[..., None]


def finish(img, seed, desat):
    r = np.random.default_rng(seed)
    g = r.normal(0, 2.2, (FH, W)).astype(np.float32) + 0.8 * r.normal(0, 2.2, (FH // 2 + 1, W // 2 + 1)).astype(np.float32).repeat(2, 0).repeat(2, 1)[:FH, :W]
    img = img + g[..., None]
    lum = img @ np.array([0.299, 0.587, 0.114], np.float32)
    img = img * (1 - desat) + lum[..., None] * desat
    return np.clip(img, 0, 255)


def stones(seed, cw, ch, warp, bevel):
    """Slab fields: gap (px to the joint), per-slab value, a bevelled height (domed slabs, sunk joints) and its lighting."""
    gap, sv = voronoi(seed, cw, ch, warp)
    slab = smooth(gap, 0.5, bevel)
    broad = fbm(seed + 3, 200, 3)
    fine = fbm(seed + 4, 26, 3)
    hh = blur(slab, 1.2) * 0.75 + broad * 0.35 + fine * 0.06
    lit = relief(hh, 95)
    return gap, sv, slab, broad, fine, lit


def fire():
    """Basalt slabs, violet-grey and ash-dusted, a few seams still ember-lit with a soft bleed; scorch shadows."""
    gap, sv, slab, broad, fine, lit = stones(1101, 230, 150, 70, 10.0)
    grain = fbm(1104, 7, 2)
    rock = np.clip(0.34 + 0.34 * (sv - 0.5) + 0.22 * (broad - 0.5) + 0.12 * (fine - 0.5) + 0.05 * (grain - 0.5) + 0.42 * lit, 0, 1)
    img = tint(rock, [(0, (14, 11, 15)), (0.4, (50, 42, 48)), (0.75, (92, 82, 84)), (1, (138, 124, 118))])
    img = img * (0.35 + 0.65 * slab)[..., None]  # joints sink into shadow
    seam = 1 - smooth(gap, 0.0, 3.4)
    live = smooth(fbm(1106, 300, 3), 0.56, 0.66)
    hot = seam * live
    glow = np.clip(blur(hot, 5) * 2.2 + blur(hot, 24) * 1.6, 0, 1)
    core = np.clip(blur(hot, 0.9) * 1.8, 0, 1)
    img = img * (1 - 0.6 * core[..., None])
    em = glow[..., None] * np.asarray([(150, 46, 14)], np.float32) + core[..., None] * np.asarray([(235, 120, 36)], np.float32)
    ash = smooth(fbm(1107, 120, 4, 2.4), 0.62, 0.86) * slab
    img = img * (1 - 0.3 * ash[..., None]) + ash[..., None] * 0.3 * np.asarray([(128, 116, 112)], np.float32)
    scorch = smooth(fbm(1108, 220, 3), 0.6, 0.78)
    img = img * (1 - 0.4 * scorch)[..., None]
    img = persp(img)
    img = stage_light((210, 90, 40), 1.0, (66, 32, 34), img) + persp(em) * (1 - 0.6 * np.exp(-SY / 30.0))[..., None]  # embers glow on their own
    return finish(img, 1109, 0.12)


def water():
    """Wet slate flags with dark weedy joints, a few standing pools mirroring a cold teal light, a caustic shimmer."""
    gap, sv, slab, broad, fine, lit = stones(1201, 180, 120, 40, 7.0)
    v = np.clip(0.34 + 0.30 * (sv - 0.5) + 0.2 * (broad - 0.5) + 0.12 * (fine - 0.5) + 0.42 * lit, 0, 1)
    img = tint(v, [(0, (6, 14, 20)), (0.4, (28, 48, 58)), (0.75, (62, 90, 98)), (1, (120, 150, 152))])
    joint = 1 - slab
    img = img * (1 - 0.65 * joint)[..., None] + (joint * 0.65)[..., None] * np.asarray([(14, 34, 28)], np.float32)
    wet = smooth(fbm(1211, 90, 3), 0.45, 0.7)  # wet sheen: a cool specular lift on the slabs
    img = img + (wet * np.clip(lit, 0, 1) * 34)[..., None] * np.asarray([(0.6, 0.9, 1.0)], np.float32)
    pool = smooth(fbm(1205, 210, 4, 1.8), 0.62, 0.68)
    sheen = blur(fbm(1206, 50, 3, 3.5), 2)
    refl = tint(0.25 + 0.55 * sheen, [(0, (8, 24, 34)), (0.6, (40, 92, 106)), (1, (118, 178, 186))])
    img = img * (1 - 0.8 * pool[..., None]) + refl * 0.8 * pool[..., None]
    rim = np.clip(blur(pool, 1.5) - blur(pool, 5), 0, 1)
    img = img + (rim * 120)[..., None] * np.asarray([(0.55, 0.9, 1.0)], np.float32)
    a = np.abs(fbm(1207, 80, 3, 1.4) - 0.5)
    b = np.abs(fbm(1208, 56, 3, 1.0) - 0.5)
    caus = blur(np.exp(-(np.minimum(a, b) / 0.035) ** 2), 1.2) * smooth(fbm(1209, 260, 2), 0.45, 0.8)
    img = img + (caus * (8 + 26 * pool))[..., None] * np.asarray([(0.5, 0.9, 1.0)], np.float32)
    img = persp(img)
    img = stage_light((60, 160, 180), 1.0, (28, 56, 68), img)
    return finish(img, 1210, 0.14)


def earth():
    """Ruined flagstones half-sunk in packed earth, moss crowding the joints, root ridges, pebbles, a few pale spore glints."""
    gap, sv, slab, broad, fine, lit = stones(1301, 240, 150, 60, 11.0)
    ruin = smooth(fbm(1305, 300, 3), 0.30, 0.44)  # where the old paving survives
    soil_h = fbm(1302, 60, 4)
    soil = np.clip(0.3 + 0.3 * (soil_h - 0.5) + 0.2 * (broad - 0.5) + 0.3 * relief(blur(soil_h, 1.5), 40), 0, 1)
    img = tint(soil, [(0, (16, 13, 9)), (0.45, (58, 48, 34)), (0.8, (98, 84, 60)), (1, (132, 116, 84))])
    st = np.clip(0.38 + 0.3 * (sv - 0.5) + 0.15 * (fine - 0.5) + 0.42 * lit, 0, 1)
    stone = tint(st, [(0, (20, 20, 18)), (0.45, (72, 70, 58)), (0.8, (122, 118, 98)), (1, (168, 160, 132))])
    s = slab * ruin
    img = img * (1 - s[..., None]) + stone * s[..., None]
    img = img * (1 - 0.65 * (1 - slab) * ruin)[..., None]
    moss = np.clip(smooth(fbm(1306, 110, 4), 0.56, 0.72) * (1 - 0.7 * s) + (1 - smooth(gap, 0, 6)) * ruin * 0.9, 0, 1)
    mcol = tint(0.2 + 0.6 * blur(fbm(1307, 14, 3), 1.2) + 0.25 * lit, [(0, (16, 24, 12)), (0.6, (48, 62, 28)), (1, (88, 100, 48))])
    img = img * (1 - 0.75 * moss[..., None]) + mcol * 0.75 * moss[..., None]
    root = np.exp(-((fbm(1308, 240, 3, 2.5) - 0.5) / 0.02) ** 2) * smooth(fbm(1309, 260, 2), 0.5, 0.7)
    rh = blur(root, 2.0)
    img = img * (1 - 0.5 * rh)[..., None] + (np.clip(relief(rh, 40), 0, 1) * 60 * rh)[..., None] * np.asarray([(0.9, 0.8, 0.6)], np.float32)
    r = np.random.default_rng(1310)
    grit = np.zeros((GH, W), np.float32)
    for x, y, sz in r.random((700, 3)):
        cx, cy, rad = int(x * W), int(y * GH), 2 + sz * 5
        y0, y1, x0, x1 = max(0, cy - 9), min(GH, cy + 10), max(0, cx - 9), min(W, cx + 10)
        d = ((XX[y0:y1, x0:x1] - cx) ** 2 + (YY[y0:y1, x0:x1] - cy) ** 2) / (rad * rad)
        grit[y0:y1, x0:x1] = np.maximum(grit[y0:y1, x0:x1], np.sqrt(np.clip(1 - d, 0, 1)))
    grit *= 1 - s
    img = img + (relief(blur(grit, 0.8), 6) * 40 * grit)[..., None] - (blur(grit, 3) * 14)[..., None]
    spore = np.zeros((GH, W), np.float32)
    for x, y in r.random((160, 2)):
        spore[int(y * (GH - 1)), int(x * (W - 1))] = 1.0
    spore = np.clip(blur(spore * moss, 1.4) * 9, 0, 1)
    img = img + spore[..., None] * np.asarray([(110, 150, 70)], np.float32)
    img = persp(img)
    img = stage_light((170, 160, 80), 1.0, (48, 54, 34), img)
    return finish(img, 1311, 0.12)


def air():
    """Pale veined sky-stone in big worn slabs, thin cloud swept across it by the wind, a cool lavender light."""
    gap, sv, slab, broad, fine, lit = stones(1401, 290, 170, 50, 8.0)
    v = np.clip(0.42 + 0.26 * (sv - 0.5) + 0.2 * (broad - 0.5) + 0.1 * (fine - 0.5) + 0.36 * lit, 0, 1)
    img = tint(v, [(0, (26, 26, 40)), (0.4, (78, 78, 104)), (0.75, (130, 130, 156)), (1, (190, 188, 206))])
    img = img * (0.45 + 0.55 * slab)[..., None]
    for seed, w in ((1405, 0.010), (1415, 0.006)):
        vein = np.exp(-((fbm(seed, 170, 4, 1.4) - 0.5) / w) ** 2) * smooth(fbm(seed + 1, 240, 2), 0.35, 0.7)
        img = img * (1 - 0.35 * blur(vein, 0.7))[..., None]
        img = img + (blur(np.roll(vein, 2, 0), 1.0) * 26)[..., None] * np.asarray([(0.9, 0.85, 1.0)], np.float32)
    for seed, cell, lo, hi, a in [(1407, 280, 0.58, 0.88, 0.34), (1408, 120, 0.62, 0.9, 0.22)]:
        m = smooth(fbm(seed, cell, 5, 4.5), lo, hi)
        img = img * (1 - 0.25 * np.roll(blur(m, 8), 16, 0))[..., None]  # the cloud's faint shadow
        img = img * (1 - a * m[..., None]) + np.asarray([(200, 200, 224)], np.float32) * a * m[..., None]
    img = persp(img)
    img = stage_light((150, 140, 220), 1.0, (80, 80, 112), img)
    return finish(img, 1409, 0.14)


def main(out):
    """Each stage is quantised on its own (64 colours, median cut, Floyd-Steinberg so the broad light has no bands; all deterministic) and the four palettes are packed
    into one 256-entry PNG palette, so a rare colour of one stage (an ember) never borrows another stage's swatch."""
    idx, pal = [], []
    for k, stage in enumerate((fire, water, earth, air)):
        rgb = Image.fromarray(stage().astype(np.uint8))
        q = rgb.quantize(colors=64, method=Image.Quantize.MEDIANCUT, dither=Image.Dither.NONE)
        q = rgb.quantize(palette=q, dither=Image.Dither.FLOYDSTEINBERG)
        p = q.getpalette()[:64 * 3]
        pal += p + [0] * (64 * 3 - len(p))
        idx.append(np.asarray(q, np.uint8) + 64 * k)
    im = Image.fromarray(np.concatenate(idx, 0), "P")
    im.putpalette(pal)
    im.save(out, optimize=True)
    print(out, os.path.getsize(out))


main(sys.argv[1])
